def flatten_nested(nested_lists):
    for sublist in nested_lists:
        yield from sublist

tree = [[1, 2], [3, 4], [5]]
print(list(flatten_nested(tree)))

def gen_with_return():
    yield 1
    return 'Done'

g = gen_with_return()
print('Yielded:', next(g))
try:
    next(g)
except StopIteration as exc:
    print('StopIteration payload:', exc.value)
